import java.util.Date;

@Slf4j
public class DateTest {
    public static void main(String[] args) throws InterruptedException {
        SimpleDateFormat sdf = new SimpleDateFormat("yyyyMMddHHmmss");
        sdf.setLenient(false);
        try
        {
            Date d1 = sdf.parse("20221210091010");
            Date target = sdf.parse("20221210121010");
            Date d3 = sdf.parse("20221210111010");

            if (target.compareTo(d1) >= 0) {
                if (target.compareTo(d3) <= 0) {
                    System.out.println("target is in between d1 and d2");
                } else {
                    System.out.println("target is NOT in between d1 and d2");
                }
            } else {
                System.out.println("target is NOT in between d1 and d2");
            }
        }catch(Exception e)
        {
            e.printStackTrace();
        }

    }
}

