package com.hanwha.management;

import lombok.extern.slf4j.Slf4j;
import org.springframework.util.StopWatch;
import org.springframework.web.client.RestTemplate;

import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;

@Slf4j
public class LoadTestAsync {

    static AtomicInteger counter = new AtomicInteger(0);

    public static void main(String[] args) throws InterruptedException,BrokenBarrierException {
        ExecutorService es = Executors.newFixedThreadPool(100);
        RestTemplate rt = new RestTemplate();
        String url = "http://localhost:8080/api/hello";

        CyclicBarrier barrier = new CyclicBarrier(101);

        StopWatch main = new StopWatch();
        main.start();

        for(int i=0;i<100;i++){
            es.submit(() -> {
                int idx = counter.addAndGet(1);
                try {
                    barrier.await();
                } catch (InterruptedException e) {
                    throw new RuntimeException(e);
                } catch (BrokenBarrierException e) {
                    throw new RuntimeException(e);
                }

                log.info("Thread " + idx);
                StopWatch sw = new Stop

                  throw new RuntimeException(e);
                }

                log.info("Thread " + idx);
                StopWatch sw = new StopWatch();
                sw.start();
                String result = rt.getForObject(url, String.class,idx);
                sw.stop();
                log.info("Elapsed : {} {} result {} ",idx,sw.getTotalTimeMillis(),result);

            });
        }
        try {
            barrier.await();
        } catch (BrokenBarrierException e) {
            throw new RuntimeException(e);
        }
        es.shutdown();
        es.awaitTermination(100, TimeUnit.SECONDS);

        main.stop();

        log.info("Elapsed : {}",main.getTotalTimeMillis());

    }
}

