		@GetMapping("/service1")
		public Mono<String> service1(String req){

            try {
                Thread.sleep(1000);
            } catch (InterruptedException e) {
                throw new RuntimeException(e);
            }

            return Mono.just(req + "/service1");
		}

		@GetMapping("/service2")
