Java Method: com.hanwha.management.interceptor.web.UserInfoInterceptor.preHandle(HttpServletRequest,HttpServletResponse,Object)
{
    Authentication authentication = SecurityContextHolder.getContext().getAuthentication();
    if (authentication != null && authentication.getPrincipal() instanceof User) {
        User user = (User) authentication.getPrincipal();
        String userId = user.getUsername();
        ApplicationContext applicationContext = WebApplicationContextUtils.getWebApplicationContext(request.getServletContext());
        UserInfoTokenUtil tokenUtil = applicationContext.getBean(UserInfoTokenUtil.class);
        UserMainDto mainDto = tokenUtil.read(userId);
        UserContext context = applicationContext.getBean(UserContext.class);
        if (mainDto != null) {
            context.setUserInfo(mainDto.getUserInfo());
        }
        FilterHandler filterHandler = applicationContext.getBean(FilterHandler.class);
        filterHandler.executeFilter(request, response);
    }
    return HandlerInterceptor.super.preHandle(request, response, handler);
}

