                UserMainDto dto = tokenUtil.read(user.getUsername());
                valueObject.setModSeq(String.valueOf(dto.getUserInfo().getSeq()));
                valueObject.setModDt(ExtensionUtil.getFullNowDate());
            }
            invocation.getArgs()[1] = valueObject;
        }
    } else if (sql.startsWith("INSERT")) {
        if (parameterObject instanceof SQLCommonDto) {
