    return new UserInfoDetail(userDto.getUserId(), userDto.getPassword(), authorities, userDto.getSiteCd(), userDto.getUserName(), userDto.getActivated(), userDto.getLastAccessIp(), userDto.getLastAccessTime(), userRoleCd);
}

