Java Method: com.hanwha.management.biz.service.AuthService.reissue(TokenDto)
{
    if (!tokenProvider.validateToken(tokenRequestDto.getRefreshToken())) {
        throw new RuntimeException("Refresh Token 이 유효하지 않습니다.");
    }
    Authentication authentication = tokenProvider.getAuthentication(tokenRequestDto.getRefreshToken());
    User detail = (User) authentication.getPrincipal();
    if (!userInfoTokenUtil.hasKey(detail.getUsername())) {
        throw new LoginException(LoginErrorConstants.LOGOUT_USER.getCode(), LoginErrorConstants.LOGOUT_USER.getMessage());
    }
    UserMainDto tokenDto = userInfoTokenUtil.read(detail.getUsername());
    String refreshToken = tokenDto.getRefreshToken();
    if (!refreshToken.equals(tokenRequestDto.getRefreshToken())) {
        throw new LoginException(LoginErrorConstants.USER_TOKEN_ERROR.getCode(), LoginErrorConstants.USER_TOKEN_ERROR.getMessage());
    }
    TokenDto resultDto = null;
    if (!tokenProvider.refreshTokenPeriodCheck(tokenRequestDto.getRefreshToken())) {
        resultDto = tokenProvider.createToken(authentication);
        UserDto userInfo = UserDto.builder().userId(tokenDto.getUserInfo().getUserId()).userName(tokenDto.getUserInfo().getUserName()).userRoleCd(tokenDto.getUserInfo().getUserRoleCd()).siteCd(tokenDto.getUserInfo().getSiteCd()).activated(tokenDto.getUserInfo().getActivated()).build();
        UserMainDto dto = UserMainDto.builder().userInfo(userInfo).accessToken(resultDto.getAccessToken()).refreshToken(resultDto.getRefreshToken()).build();
        userInfoTokenUtil.update(dto);
    } else {
        resultDto = tokenProvider.createAccessToken(authentication);
        log.info("Token의 유효기간의 3일 이상 지났 습니다.");
    }
    return resultDto;
}

