Java Method: com.hanwha.management.biz.controller.ResourceController.loadResource(ResourceDto)
{
    String siteCd = dto.getSiteCd();
    if (dto.getSiteCd() == null) {
        siteCd = ExtensionUtil.getProperty("default.site-cd");
    }
    CodeDetailSearchDto langDto = CodeDetailSearchDto.builder().groupCd("LANG_CD").langCd("ko").build();
    langDto.setSiteCd(siteCd);
    List<CodeDetailDto> codeList = codeService.selectCodeDetailList(langDto);
    Map<String, Object> resultResourceMap = new HashMap<>();
    codeList.forEach(lang -> {
        List<MessageDto> messageList = messageService.getAllMessage(getLang(lang.getCodeCd()), userContext.getUserSiteCd());
        Map<String, String> resourceMap = new HashMap<>();
        messageList.forEach(message -> {
            resourceMap.put("M_" + message.getResourceLabel(), message.getResourceCd());
        });
        List<LabelDto> labelList = labelService.getAllLabel(getLang(lang.getCodeCd()), userContext.getUserSiteCd());
        labelList.forEach(label -> {
            resourceMap.put("L_" + label.getResourceLabel(), label.getResourceCd());
        });
        resultResourceMap.put(lang.getCodeCd(), resourceMap);
    });
    return ResultUtil.success(resultResourceMap);
}

