{
    LoggerContext loggerContext = (LoggerContext) LoggerFactory.getILoggerFactory();
    List<LoggerInfo> logList = loggerContext.getLoggerList().stream().map(logger -> LoggerInfo.builder().name(logger.getName()).level(logger.getLevel() != null ? logger.getLevel().toString() : "NULL").effectiveLevel(logger.getEffectiveLevel().toString()).build()).collect(Collectors.toList());
    List<LogLevelDto> result = new ArrayList<>();
    logList.forEach(log -> {
        if (log.getName().startsWith(searchDto.getKeyword())) {
            result.add(LogLevelDto.builder().loggerName(log.getName()).build());
        }
    });
    return ResultUtil.success(result);
}

