{
    startList.forEach(detail -> {
        if (detail.getStatus().equals("S")) {
            log.info("Start batch Status {}", batchTaskScheduler.isBatchStart(detail));
            if (!batchTaskScheduler.isBatchStart(detail)) {
                batchTaskScheduler.startScheduler(detail);
            }
        } else if (detail.getStatus().equals("E")) {
            log.info("End batch Status {}", batchTaskScheduler.isBatchStart(detail));
            if (batchTaskScheduler.isBatchStart(detail)) {
                batchTaskScheduler.cancelScheduledTask(detail);
            }
        }
    });
}

