Java Method: com.hanwha.management.biz.controller.AuthController.authorize(LoginDto,HttpServletRequest)
{
    loginDto.setIp(ExtensionUtil.getClientIP(request));
    UserMainDto resultInfo = authService.login(loginDto);
    MenuDto dto = new MenuDto();
    dto.setLangCd(loginDto.getLangCd());
    dto.setSiteCd(resultInfo.getUserInfo().getSiteCd());
    dto.setMenuRoleCd(resultInfo.getUserInfo().getUserRoleCd());
    List<MenuListDto> menuList = menuService.selectRoleCheckMenuList(dto);
    resultInfo.setMenuList(menuList);
    HttpHeaders httpHeaders = new HttpHeaders();
    httpHeaders.add(JwtAuthenticationFilter.AUTHORIZATION_HEADER, "Bearer " + resultInfo.getAccessToken());
    return new ResponseEntity<>(resultInfo, httpHeaders, HttpStatus.OK);
}

